    self.frame = parse_number(row,"frame", 0)
    self.fuseFrame = parse_number(row,"skillFuse", 0)
    self.attackPos = Vector3.New(SafeUnpack(Tools.splitToNum(parse_string(row,"attackPos", ''), ';')))

